def drive(me, enemy, arena):
    # bearing to enemy (degrees, -180..180, positive left)
    b = bearing_to(enemy.x, enemy.y)
    # turn sharply if not roughly aligned, otherwise full throttle forward
    if b > 10:
        return (-1.0, 1.0)   # turn left
    elif b < -10:
        return (1.0, -1.0)   # turn right
    else:
        return (1.0, 1.0)    # charge forward

def weapons(me, enemy, arena):
    cmds = []
    w = me.weapons.get('front')
    if not w or w['type'] != 'flipper':
        return cmds

    # self‑right when upside down
    if me.inverted and w.get('ready') and w.get('shots_left', 0) > 0:
        cmds.append(self_right())

    # fire flipper when close enough
    if distance_to(enemy.x, enemy.y) < 0.9 and w.get('ready') and w.get('shots_left', 0) > 0:
        cmds.append(flip('front'))

    return cmds
